insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (149,'دفاتر الشروط النموذجية','ملف تلزيم نموذجي لشراء اللوازم بموجب مناقصة أو طلب عروض أسعار','2026-11-10','https://www.ppa.gov.lb/ar/pages/details/149','{"https://admin.ppa.gov.lb/storage/listing-pages/files/1794304939-SBD-Goods-PPA-Nov26-Ar-Final.docx","https://admin.ppa.gov.lb/storage/listing-pages/files/1794304959-SBD-Goods-PPA-Nov26-Ar-Final.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1794334931-SBD-Goods-User Guide-PPA-Nov26-Ar-Final.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1794304939-SBD-Goods-PPA-Nov26-Ar-Final.docx","https://admin.ppa.gov.lb/storage/listing-pages/files/1794304959-SBD-Goods-PPA-Nov26-Ar-Final.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1794334931-SBD-Goods-User Guide-PPA-Nov26-Ar-Final.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=149),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "ملف تلزيم نموذجي\nلشراء اللوازم\nبموجب مناقصة أو طلب عروض أسعار\nالإصدار 1.0\nتشرين الثاني 2026\nالفهرس\nالقسم الأول: تعليمات للعارضين 7\n‌أ- عام 7\n1. نطاق عملية الشراء 7\n2. الممارسات المحظورة 7\n3. العارضون المؤهلون 7\n4. تكلفة العروض 8\n5. لغة العرض 8\n‌ب- محتويات ملف التلزيم 8\n6. أقسام ملف التلزيم 8\n7. إيضاح حول ملف التلزيم، زيارة الموقع، الاجتماع السابق لطلب عروض\nالاسعار 9\n8. تعديل ملف التلزيم 9\n‌ج- إعداد العروض 9\n9. المستندات المكوّنة للعرض 9\n10. كتب العرض 10\n11. العروض البديلة 10\n12. أسعار العروض والحسومات 10\n13. العملة 10\n14. وثائق تثبت مؤهلات العارض 10\n15. مدة سريان العرض 10\n16. ضمان العرض 11\n17. شكل وتوقيع العرض 11\n‌د- تقديم وفتح العروض 11\n18. تقديم العروض 11\n19. سحب وتعديل العروض 12\n20. الموعد النهائي لتقديم العروض 12\n21. العروض المتأخّرة 12\n22. فتح العروض 12\n‌ه- فحص وتقييم العروض 13\n23. السرية 13\n24. توضيح العروض 13\n25. تقييم العروض 13\n26. منهجية التقييم 14\n27. تصحيح الأخطاء الحسابية 14\n28. التحويل إلى العملة الموحّدة 14\n29. تأهيل العارض 14\n30. حق الجهة الشارية في قبول أيّ عرض ورفض أيّ أو كلّ العروض 14\n‌و- إرساء العقد 15\n31. المعايير 15\n32. التبليغ 15\n33. توقيع العقد 16\n‌ز- الشكاوى 16\n34. إجراءات الشكاوى 16\nالقسم الثاني: جدول البيانات 17\n1.نطاق عملية الشراء 17\n3. العارضون المؤهلون 17\n5. لغة العرض 17\n7. الإستيضاح، الزيارة الميدانية، اجتماع ما قبل العرض 18\n9.المستندات المكوّنة للعرض 19\n12.أسعار العرض 19\n13.عملة العرض 19\n14. الوثائق التي تثبت أهلية العارض 19\n15. صلاحية العرض 21\n16. قيمة وصلاحية ضمان العرض 21\n18. تقديم العروض 22\n19. سحب العرض وتعديله Error! Bookmark not defined.\n20. الموعد النهائي لتقديم العروض 23\n22. فتح العروض 23\n31. معايير الإرساء 24"}, {"o": 1, "l": null, "b": "القسم الثالث: منهجية التقييم 25\n‌أ- منهجية تقييم العرض 25\n1. الفحص الأولي 25\n2. الفحص الدقيق 25\n3. التقييم الفني 26\n4. التقييم المالي 27\n5. تصحيح الأخطاء الحسابية 27\n6. إرساء العقد 28\n‌ب- شروط التأهيل 28\n7. الاهلية 28\n8. الوضع المالي 28\n9. الخبرة 28\n10. المعايير البيئية والاجتماعية والصحية والسلامة (ESHS) 29\n11. متطلبات محددة فيما يتعلق بتحالف الشركات 29\n12. قدرات الموظفين (في حال الانطباق) 29\nالقسم الرابع: معايير الأهلية والتأهيل (Eligibility and Qualification\nCriteria) 30\nالجدول رقم 1: الأهلية 30\n‌أ- الجدول رقم 2: الوضع المالي 31\n‌ب- الجدول رقم 3: الخبرة 32\n‌ج- الجدول رقم 4: مطابقة معايير البيئة والصحة والسلامة (ESHS) 33\n‌د- الجدول رقم 6: الموظفون Error! Bookmark not defined.\nالقسم الخامس: النماذج 34\n1. نموذج كتاب العرض الاداري والفني (التعهد) للاشتراك في المناقصة\nالعمومية / طلب عروض أسعار 35\n2. ميثاق النزاهة 38\n3. نماذج الأهلية (ُEligibility Forms) 40\nنموذج الأهلية (E1) - معلومات العارض 40\n4. نماذج الأهلية (ُEligibility Forms) 41\nنموذج (E2) - معلومات شركاء تحالف الشركات 41\n5. نماذج مؤهلات العارض Qualification Forms 42\nنموذج (Q1) – الأداء المالي السابق 42\n6. نماذج مؤهلات العارض Qualification Forms 44\nنموذج (Q2) – متوسط حجم الأعمال السنوي 44\n7. نماذج مؤهلات العارض Qualification Forms 46\nنموذج (Q3) - الخبرة المحددة (الخاصة) 46\n8. نماذج مؤهلات العارض Qualification Forms 48\nنموذج (ESHS) مطابقة معايير البيئة والصحة والسلامة 48\n9. نموذج جدول الأسعار 50\n10. نموذج ضمان العرض 51\nالقسم السادس: المتطلبات 55\n1. نطاق ومتطلبات الشراء 55\n2. متطلبات التسليم 56\n3. المواصفات الفنية 57\n4. الرسومات 58\nالقسم السابع : شروط وأحكام العقد 59\n1 الشروط العامة للعقد 59\n1 التعاريف 59\n2 وثائق العقد 60"}, {"o": 2, "l": null, "b": "3 الممارسات المحظورة 60\n4 التفسيرات 61\n5 القانون السائد 62\n6 اللغة 62\n7 تحالف الشركات 62\n8 الأهلية 62\n9 الإشعارات 63\n10 المهل 63\n11 نطاق التلزيم 63\n12 مباشرة العمل، التسليم والوثائق 63\n13 التقيد بالأحكام المنظمة للعمل 64\n14 قيمة العقد 64\n15 شروط الدفع 64\n16 الضرائب والرسوم 65\n17 ضمان حسن التنفيذ 65\n18 حقوق الملكية الفكرية والأدبية 66\n19 سرية المعلومات 66\n20 التعاقد الثانوي 67\n21 المتطلبات والرسومات 67\n22 التأمين 67\n23 استلام اللوازم والخدمات الملحقة بها 67\n24 غرامات التأخير 67\n25 التحصين والتعويض من انتهاك براءات الاختراع 68\n26 تعديل القوانين والأنظمة ذات الصلة 69\n27 الظروف القاهرة 69\n28 تعدل الكميات وأوامر التغيير وتعديل العقد 69\n29 تمديد مهلة العقد 70\n30 أسباب انتهاء العقد ونتائجه 70\n31 حل النزاعات 72\n32 التنازل عن العقد 72\n2 الشروط الخاصة للعقد 73\n3 نماذج العقود 77\n1. كتاب القبول 77\n2. اتفاقية العقد 79\nملف تلزيم\nلشراء اللوازم\nبموجب مناقصة عمومية أو طلب عروض اسعار\n -------------------------------------------------- --------------------\n الصادر في\n المرجع\n الجهة الشارية\n المشروع\n -------------------------------------------------- --------------------\nالقسم الأول: تعليمات للعارضين\nInstructions To Bidders\nعام\nنطاق عملية الشراء\nتدعو الجهة الشارية، الأشخاص والجهات والشركات المؤهلة لتقديم عروضها\nلتأمين المشروع المحدد في متطلبات التوريد (القسم السادس) وفقاً للشروط\nالمبينّة في ملف التلزيم هذا وفي شروط العقد العامة والخاصة. يطبّق على ملف\nالتلزيم قانون الشراء العام والأنظمة الأخرى المرعية الإجراء، وكل خلاف\nينشأ عن تنفيذ ملف التلزيم أو تفسيره تفصل فيه هيئة الاعتراضات والمراجع\nالإدارية أو القضائية المختصة.\nتغطّى قيمة هذا الشراء من الاعتمادات المخصصة له من ضمن مصدر التمويل المحدد"}, {"o": 3, "l": null, "b": "في جدول البيانات (القسم الثاني).\nيمكن الإطلاع على ملف التلزيم والإستحصال على نسخة منه عن المنصة\nالالكترونية المركزية على العنوان التالي : www.ppa.gov.lb كما على الموقع\nالالكتروني للجهة الشارية.\nتسلّم اللوازم والخدمات المرتبطة بها المحدّدة في جدول المتطلبات (القسم\nالسادس من ملف التلزيم) وبحسب ما هو مطلوب، وخلال الفترة وفي الموقع\nالمحدّدين في جدول المتطلّبات، وذلك على أساس شروط التسليم المنصوص عنها في\nالقسمين السادس (المتطلبات) والسابع (العقد) من ملف التلزيم.\nالممارسات المحظورة \nيجب على كل من موظفي الجهة الشارية، العارضين، الملتزم/الملتزمين وعلى\nمسؤوليهم، وعلى مديريهم أو الموظفين المعتمدين أو الشركات التابعة أو\nالوكلاء أو الممثلين التابعين لهم، أن يلتزموا بأعلى مستوى من الشفافية\nوالنزاهة أثناء عملية تلزيم وتنفيذ العقد.\nيكون للمارسات المحظورة والمصطلحات الأخرى الواردة في هذا البند، هنا أو في\nالقسم السابع (شروط وأحكام العقد)، المعنى المحدَد في قانون الشراء العام\nرقم 244/2021 وتعديلاته وفي سياسة وإجراءات الشراء الصادرة عن هيئة الشراء\nالعام، وفي المراسيم التطبيقية.\nالعارضون المؤهلون\nهم العارضون الذين يستوفون معايير الأهلية والتأهيل المنصوص عليها في القسم\nالرابع (معايير الاهلية والتأهيل).\nيمكن أن يكون العارض شخصاً طبيعياً، أو معنوياً (كيان خاص، كيان مملوك من\nالحكومة أو أي مزيج من هذه الكيانات على شكل مشروع مشترك، اتحاد أو جمعية\nمشروع مشترك، أو تحالف شركات).\nفي حالة تحالف الشركات يعتبر شركاء تحالف الشركات مسؤولين بالتكافل\nوالتضامن فيما بينهم عن تقديم وتنفيذ العرض الخاص بهم.\nيجب على تحالف الشركات تعيين ممثل عنهم (الشريك الرئيس) يكون لديه سلطة\nإجراء جميع الأعمال نيابة عن أي وجميع شركاء تحالف الشركات أثناء عملية\nالشراء."}, {"o": 4, "l": null, "b": "لا يجوز لـتحالف الشركات تغيير تكوينها ووضعها القانوني بعد تقديم العرض.\nلا يجوز لشركة أو عضو في تحالف الشركات أن يشارك إلا في عرض واحد للمناقصة،\nإما فرديا أو كشريك في تحالف الشركات. وسيؤدي تقديم أو مشاركة العارض في\nأكثر من عرض واحد إلى اعتبار جميع العروض المقدمة منه غير مؤهلة.\nتكلفة العروض\nيتحمل العارض جميع التكاليف المرتبطة بإعداد وتقديم العروض الخاصة به، ولا\nتتحمل الجهة الشارية أية مسؤولية عن هذه التكاليف، بصرف النظر عن مسار أو\nنتائج عملية الشراء.\n لغة العرض\nيجب كتابة العروض، وكذلك جميع المراسلات والوثائق المتعلقة بها والمتبادلة\nبين المشترك والجهة الشارية، باللغة العربية، ويمكن تقديمها أيضاً باللغة\nالمحددة في جدول البيانات، وعند التعارض بين اللغتين يؤخذ بالنص الوارد\nباللغة العربية.\nمحتويات ملف التلزيم\nأقسام ملف التلزيم\nيتكوّن ملف التلزيم من الأقسام التي تحدّد إجراءات الشراء الموضحة أدناه،\nويجب قراءتها بالاقتران مع أية تعديلات أو إضافات صادرة وفقًا لـتعليمات\nللعارضين.\n- القسم الأول: تعليمات للعارضين\n- القسم الثاني: جدول البيانات\n- القسم الثالث: منهجية التقييم\n- القسم الرابع: معايير الأهلية والتأهيل\n- القسم الخامس: النماذج\n- القسم السادس: المتطلبات\n- القسم السابع: شروط وأحكام العقد\nإن الاعلان عن المناقصة العمومية أو الدعوة لطلب عروض الاسعار الصادرة عن\nالجهة الشارية ليستا جزءاً من ملف التلزيم.\nيجب أن يقوم العارض بالإطلاع على جميع التعليمات والنماذج والشروط والأحكام\nالخاصة بالعقد والمتطلبات والمعلومات الأخرى الواردة في ملف التلزيم، وقد\nيؤدي عدم تقديم جميع المعلومات أو الوثائق المطلوبة إلى رفض العرض.\n إيضاح حول ملف التلزيم، زيارة الموقع، الاجتماع السابق للمناقصة العمومية او لطلب عروض الاسعار\nيحقّ للعارض تقديم طلب استيضاح خطّي حول ملفات التلزيم خلال المهلة المنصوص"}, {"o": 5, "l": null, "b": "عليها في جدول البيانات (القسم الثاني).\nتجيب الجهة الشارية على طلبات الاستيضاح خطياً وتنشر بالتزامن الايضاحات على\nالمنصة خلال المهلة المنصوص عليها في جدول البيانات (القسم الثاني).\nيمكن للعارض معاينة الموقع وفحصه والحصول بنفسه، وعلى مسؤوليته الخاصة، على\nجميع المعلومات التي قد تكون ضرورية لإعداد العرض والدخول في المناقصة،\nوتكون تكاليف هذه الزيارة على نفقته، اذا نص على ذلك جدول البيانات (القسم\nالثاني).\nتعديل ملف التلزيم \nيمكن للجهة الشارية أن تدخل تعديلات على ملف التلزيم قبل الموعد النهائي\nلتقديم العروض. في هذه الحالة، يُنشر الملف المعدّل بنفس الطريقة التي نُشر\nبها ملف التلزيم الاساسي.\nإعداد العروض\nالمستندات المكوّنة للعرض\nيتكوّن العرض من جزأين: الجزء الأوّل هو الإداري والفني، والجزء الثاني هو\nالجزء المالي. يجب تقديم هذين الجزأين في وقت واحد في غلافين مختومين\nمنفصلين، ويجب أن يحتوي الغلاف الأول فقط على المعلومات المتعلقة بالجزء\nالإداري والفني (العرض الإداري والفني) والغلاف الثاني على المعلومات\nالمتعلّقة بالجزء المالي (العرض المالي) فقط، ويجب وضع هذين الغلافين في\nغلاف خارجي موحّد مختوم ومدوّن عليه المعلومات المحددة في ملف التلزيم.\nيجب ان يتضمّن العرض الإداري والفني ما يلي:\n1. كتاب العرض الإداري والفني (او ما يُعرف بالتعهّد) مع ميثاق النزاهة\n المرفق به وفقا للفقرة (10) من التعليمات للعارضين.\n2. تفويض رسمي حسب الأصول، يثبت صفة الشخص (الأشخاص) الذي (الذين) يوقّعون\n على العرض وسلطة التوقيع عليه وفقا للفقرة (17) من التعليمات\n للعارضين.\n3. ضمان العرض وفقاً للفقرة (16) من التعليمات للعارضين.\n4. العرض البديل - الجزء الفني إذا كان مسموحاً به وفقا للفقرة (11) من\n التعليمات للعارضين.\n5. الوثائق المكتملة التي تثبت أهلية العارض ومؤهلاته وفقاً للفقرة (14) من\n التعليمات للعارضين."}, {"o": 6, "l": null, "b": "6. اتفاقية تحالف الشركات في حالة تقديم العرض من قبل تحالف شركات.\n7. أية وثيقة أخرى محددة في جدول البيانات.\n يجب ان يتضمن العرض المالي ما يلي:\n1. جداول الأسعار وفقا للفقرة (12) من التعليمات للعارضين.\n2. العرض البديل - الجزء المالي إذا كان مسموحاً به وفقا للفقرة (11) من\n التعليمات للعارضين.\n3. أية وثيقة أخرى محددة في جدول البيانات.\n يجب ان لا يحتوي العرض الإداري والفني على أية معلومات مالية ذات علاقة\n بسعر العرض، وإذا تضمن العرض الإداري والفني معلومات مالية جوهرية\n متعلقة بسعر العرض يُعتبر العرض غير مستجيب.\nكتب العرض\nيجب على العارض تقديم كتاب العرض الإداري والفني وكتاب العرض المالي، بما\nيتوافق مع متطلبات ملف التلزيم هذا، وباستخدام النماذج المبيّنة في القسم\nالخامس (نماذج العرض)، ويجب إكمال هذه النماذج دون أية تعديلات على نصوصها،\nولن يتمّ قبول أية بدائل تغيّر في نص النماذج، ويجب ملء جميع الفراغات\nبالمعلومات المطلوبة.\nعلى العارض أن يرفق ميثاق النزاهة بكتاب العرض الإداري والفني وفق النموذج\nالمرفق بنموذج كتاب العرض الإداري والفني الوارد في القسم الخامس (نماذج\nالعرض) موقّعاً من الشخص أو الأشخاص المخوّلين بالتوقيع باسم العارض دون إدخال\nاي تعديلات على نصوصه.\nالعروض البديلة\nما لم يذكر خلاف ذلك في جدول البيانات، لن يتم النظر في العروض البديلة.\nأسعار العروض والحسومات\nيجب أن تكون أسعار العرض التي يقدمها العارض في عرضه متوافقة مع المتطلبات\nالمحددة في جدول المتطلبات (القسم السادس).\n العملة\nيحدد جدول البيانات (القسم الثاني) عملة العقد.\n وثائق تثبت مؤهلات العارض\nلتحديد مؤهلات العارض لتنفيذ العقد وفقاً للقسم الثالث (منهجية التقييم)،\nوالقسم الرابع (معايير الأهلية والتأهيل)، يقدّم العارض المعلومات والوثائق\nالمطلوبة في القسم الثاني (جدول البيانات) وفق النماذج المحددة في القسم\nالخامس."}, {"o": 7, "l": null, "b": "مدة سريان العرض\nيجب أن يكون العرض صالحاً للفترة المحددة في جدول البيانات.\nيجوز للجهة الشارية، في حالات استثنائية، أن تطلب من العارضين تمديد فترة\nصلاحية عروضهم لمدة إضافية. ويجوز للعارض أن يرفض هذا الطلب وأن يطلب\nإسترجاع ضمان عرضه. وفي حال قبول العارض لهذا الطلب فعليه أن يمدد فترة\nصلاحية ضمان عرضه أو أن يُقدّم ضمان عرض جديد يُغطي فترة تمديد صلاحية العرض\nالممدّد. يعتبر العارض الذي لم يمدّد ضمان عرضه، أو الذي لم يقدّم ضمان عرض\nجديد، أنه رافضٌ تمديد فترة صلاحية عرضه، ويخرج بالتالي من المنافسة.\n ضمان العرض \nعلى العارض تقديم ضمان العرض بالقيمة والعملة التي يحددها جدول البيانات في\nالقسم الثاني (في حال الانطباق). يقدّم ضمان العرض بموجب كتاب ضمان مصرفي\nغير قابل للرجوع عنه صادر عن مصرف مقبول من مصرف لبنان يبيّن أنه قابل للدفع\nعند الطلب، أو نقداً يُدفع إلى صندوق الخزينة أو إلى صندوق سلطة التعاقد، وفق\nما هو محدد في جدول البيانات، وذلك لقاء إيصال يُرفَق بمستندات العرض. يحرر\nضمان العرض باسم المشروع موضوع التلزيم لصالح الجهة الشارية.\nفي حال التلزيم على أساس مجموعات يحدّد جدول البيانات قيمة كتاب الضمان\nالمقابل لكل مجموعة على حدة.\nأي عرض غير مصحوب بضمان عرض مقبول (في حال أوجبه ملف التلزيم) سيتمّ رفضه. \nيكون ضمان العرض (في حال أوجبه ملف التلزيم) الخاص بـتحالف الشركات عادةً\nباسم تحالف الشركات. يمكن أن يكون ضمان العرض الخاص بـتحالف الشركات باسم\nشريك في التحالف بشرط أن يحدد ضمان العرض بوضوح أسماء جميع شركاء تحالف\nالشركات وينص على تقديم الضمان لصالح وبالنيابة عن التحالف.\nيعاد ضمان العرض إلى الملتزم عند تقديمه ضمان حسن التنفيذ، وإلى العارضين\nالذين لم يرس عليهم التلزيم في مهلة أقصاها بدء نفاذ العقد.\nشكل وتوقيع العرض\nيقدّم العارض مجموعة المستندات المكوّنة للعرض، وعلى المفوّض بالتوقيع على"}, {"o": 8, "l": null, "b": "العرض توقيع كافة صفحات وثائق العرض المقدّم منه.\nيجب أن يتوافق العرض المقدّم من تحالف الشركات مع المتطلبات:\n1. يتمّ التوقيع عليه بحيث يكون ملزماً قانوناً لجميع الشركاء؛\n2. يتضمن تفويض الممثل الذي يتألف من توكيل موقّع من قبل المفوضين قانوناً\n بالتوقيع نيابة عن تحالف الشركات.\nتقديم وفتح العروض\nتقديم العروض\nيتم تقديم العروض وفقاً لما يلي:\n1. تقدّم العروض وفق ما ينص عليه جدول البيانات في القسم الثاني من ملف\n التلزيم هذا لجهة كيفية تقديم العرض ومكانه وموعده النهائي.\n2. يقدم العرض خطياً وموقّعاً عليه في غلاف مختوم.\nتزوّد الجهة الشارية العارض بإيصال يبيّن فيه رقمٌ تسلسليٌّ بالإضافة إلى تاريخ\nتسلم العرض بالساعة واليوم والشهر والسنة.\nسحب وتعديل العروض\nيمكن للعارض، بعد تقديم عرضه، أن يعدّله أو أن يسحبه بموجب إشعار خطي موقّع أصولًا من ممثله المفوّض قبل الموعد النهائي لتقديم العروض، دون مصادرة ضمان عرضه. ويجب أن يرفق بالإشعار الخطي المعني العرض البديل.\n1. يجب إعداد إشعار تعديل العرض أو سحبه من قِبل العارض، وإقفاله ووضعه في\n ظرف وتسليمه، وفقاً لأحكام الفقرة 18 من هذه التعليمات إلى العارضين،\n على أن يُضاف إلى المظروفين الخارجي والداخلي، عبارة \"سحب العرض\" أو\n \"تعديل العرض\" بحسب الحالة؛\n2. يكون التعديل أو طلب سحب العرض ساري المفعول عندما تتسلمه الجهة\n الشارية قبل الموعد النهائي لتقديم العروض.\n3. لا يجوز سحب أي عرض أو تعديله خلال الفترة الممتدة بين الموعد النهائي\n لتقديم العروض وتاريخ انتهاء مدة صلاحية العرض المحددة من قبل العارض\n في كتاب العرض، أو أي فترة تمديد لهذه المدة.\nالموعد النهائي لتقديم العروض\nيجب أن تصل العروض الى العنوان المحدد قبل الساعة والتاريخ المحددان في\nجدول البيانات (القسم الثاني).\nالعروض المتأخّرة\nتُرسل العروض إلى الجهة الشارية بالبريد العام او الخاص المضمون المغفل أو"}, {"o": 9, "l": null, "b": "باليد مباشرة على العنوان المحدّد في جدول البيانات. لا يفتح أي عرض تتسلّمه\nالجهة الشارية بعد الموعد النهائي لتقديم العروض، بل يسجّل مع تاريخ وساعة\nوروده، ثم يعاد مختوماً بعد جلسة التلزيم إلى العارض الذي قدّمه.\nفتح العروض\nتفتح العروض باتّباع الإجراءات التالية:\n1. تفتح العروض لجنة التلزيم المختصة في جلسة علنية بحضور الأشخاص المأذون\n لهم في جدول البيانات (القسم الثاني)، في الوقت والمكان ووفقاً للطريقة\n المحددة في هذا الجدول.\n2. يحقّ لجميع العارضين المشاركين في عملية الشراء أو لممثّليهم المفوّضين\n وفقاً للأصول، كما يحقّ للمراقب المندوب من قبل هيئة الشراء العام حضور\n جلسة فتح العروض. كما يمكن للجهة الشارية دعوة وسائل الإعلام لحضور هذه\n الجلسة على أن تلحظ ذلك في جدول البيانات.\n3. أولاً، تُفتح المظاريف التي تحمل عبارة \"سحب العرض\" وتُتلى محتوياتها\n علناً، فيما لا يُفتح الظرف الذي يتضمن العرض المقابل ألا بمقدار التثبّت\n من هوية المفوّض بالتوقيع، بل يُعاد إلى العارض. ولا يُسمح بسحب أي عرض ما\n لم يتضمّن إشعار السحب المقابل تفويضاً صحيحاً يجيز طلب السحب، وما لم تتمّ\n تلاوة هذا الإشعار علناً أثناء جلسة فتح العروض.\n4. ثانياً، تُفتح المظاريف التي تحمل عبارة \"تعديل العرض\" وتُتلى محتوياتها\n علناً مع العرض المعني. ولا يُسمح بتعديل أي عرض ما لم يتضمّن إشعار\n التعديل المقابل تفويضاً صحيحاً يجيز طلب التعديل، وما لم تتم تلاوة هذا\n الإشعار علناً أثناء جلسة فتح العروض.\n5. بعد ذلك، تُفتح جميع المظاريف المتبقية، واحداً تلو الآخر، ويُعلن علناً ما\n يلي: اسم العارض، وما إذا كان العرض قد خضع لأي تعديل؛ ووجود أو عدم\n وجود ضمان العرض.\n6. لا تُؤخذ في الاعتبار لأغراض التقييم اللاحق إلا العروض التي تم فتحها\n وتلاوة بياناتها علناً أثناء جلسة فتح العروض."}, {"o": 10, "l": null, "b": "7. لا يجوز للجنة التلزيم مناقشة مزايا أي عرض أو رفض أي عرض، باستثناء\n العروض المقدّمة قبل انقضاء المهلة المحددة لتقديم العروض.\n8. تُعدّ الجهة الشارية محضراً لجلسة فتح العروض.\n9. يُطلب من ممثلي العارضين الحاضرين وممثل هيئة الشراء العام، في حال\n حضوره، التوقيع على لائحة الحضور. ولا يؤثّر عدم توقيع أحد العارضين على\n لائحة الحضور في صحة نتائج واجراءات الجلسة.\n10. عند الانتهاء من مرحلة التقييم الفني، لا تُفتح العروض المالية إلا\n للعارضين الذين تبيّن أن عروضهم الفنية مستوفية للمتطلبات الفنية،\n والذين حققوا الحد الأدنى لعلامة النجاح الفنية المحددة في معايير\n تقييم العروض. أما العروض المالية المقدّمة من العارضين الذين لم\n يستوفوا المتطلبات الفنية، فتبقى مقفلة، وتُعاد إلى أصحابها بعد استكمال\n عملية التقييم.\nفحص وتقييم العروض\nالسرية\nإن المعلومات المتعلقة بفحص وتوضيح وتقييم العروض والتوصيات بإرساء التلزيم\nتبقى سرية. لا يتمّ الإفصاح عن مداولات لجنة التلزيم.\nتوضيح العروض\nفي حال كانت المعلومات أو المستندات المقدّمة في العرض ناقصة أو خاطئة أو في\nحال غياب وثيقة معيّنة، يجوز للجهة الشارية الطلب خطّياً من العارض المعني\nتوضيحات حول عرضه، أو طلب تقديم أو استكمال المعلومات أو الوثائق ذات الصلة\nخلال فترة زمنية محددة، شرط أن تكون كافة المراسلات خطية واحترام مبادىء\nالشفافية والمساواة في المعاملة بين العارضين في طلبات التوضيح أو\nالاستكمال الخطية، ومع مراعاة أحكام الفقرة 3 من البند الثاني من"}, {"o": 11, "l": "المادة 21", "b": "المادة 21\nمن قانون الشراء العام.\nإذا لم يقدّم العارض توضيحات عن عرضه بحلول التاريخ والوقت المحدّدين في طلب\nالجهة الشارية للتوضيح، حق للجهة الشارية تقييم العرض في ضوء محتوياته\nواتخاذ القرار المناسب في شأنه بما في ذلك رفض العرض المقدم منه.\nتقييم العروض\nيتمّ تقييم العروض وفقاً للمادة 55 من قانون الشراء العام.\nتدرس الجهة الشارية العروض الماليّة على نحو منفصل بحيث تدرسها بعد الانتهاء\nمن تدقيق وتقييم العروض الإدارية والفنيّة.\nتعتبر الجهة الشارية العرض مستجيباً جوهرياً للمتطلّبات إذا كان يستوفي\nمتطلبات ملف التلزيم دون أي انحراف أو تحفظ أو إغفال جوهري. والانحراف أو\nالتحفظ أو الإغفال الجوهري هو الذي:\n1. إذا تمّ قبوله، سوف:\n 1. يؤثر بأي طريقة جوهرية على نطاق أو جودة أو أداء اللوازم كما هو\n محدد في القسم السادس (جدول المتطلبات)، أو\n 2. يكون من شأنه التقييد جوهرياً - بما لا يتوافق مع ملف التلزيم- على\n حقوق الجهة الشارية أو التزامات العارض بموجب العقد المقترح؛\n2. ‌إذا تمّ تصحيحه، سيؤثر بشكل غير عادل على الوضع التنافسي للعارضين\n الآخرين الذين قدّموا عروضاً مستجيبة جوهرياً.\nمنهجية التقييم\nتستخدم الجهة الشارية المعايير والمنهجيات الموضحة في القسم الثالث (منهجية\nالتقييم)، ولا تستخدم أي معايير أو منهجيات تقييم أخرى.\n تصحيح الأخطاء الحسابية\nتصحّح الأخطاء الحسابية المحضة المكتشفة أثناء فحص العروض المقدمة وفقاً\nلمنهجية التقييم (القسم الثالث) ولأحكام ملف التلزيم، وتبلّغ التصحيحات إلى\nالعارض المعني بشكل فوري.\nتقوم لجنة التلزيم بتصحيح قيمة العرض على ضوء تصحيح الأخطاء السابق ذكرها.\nويوافق العارض على أن يعتبر الرقم المصحح ملزماً له. فإذا رفض العارض قيمة\nعرضه المصححة يُرفض عرضه.\nالتحويل إلى العملة الموحّدة\nلأغراض التقييم والمقارنة، تحوّل عملة (عملات) العرض إلى عملة واحدة، كما هو"}, {"o": 12, "l": "المادة 21", "b": "محدد في القسم الثالث (منهجية التقييم).\nتأهيل العارض\nتحدّد الجهة الشارية ما إذا كان العارض الذي تم اختياره قد قدم العرض الأكثر\nفائدة من الناحية الاقتصادية والأكثر استجابة لمعايير التأهيل المحددة في\nالقسم الرابع (معايير الأهلية والتأهيل).\nيستند القرار إلى فحص مؤهّلات العارض المقدّمة من قبله، عملاً بالفقرة 14\nأعلاه.\nتكون الاستجابة الجوهرية شرطاّ أساسياً لمنح العقد للعارض.\nتحتفظ الجهة الشارية بالحقّ في التنازل عن أي انحرافات طفيفة عن المعايير\nالمؤهّلة المحدّدة في القسم الرابع (معايير الأهلية والتأهيل) التي لا تؤثر\nمادياً على قدرة العارض على تنفيذ العقد.\nحق الجهة الشارية في قبول أيّ عرض ورفض أيّ أو كلّ العروض\nتحتفظ الجهة الشارية بالحقّ في رفض أيّ عرض غير مستجيب جوهرياً، وإلغاء عملية\nالشراء ورفض جميع العروض في أي وقت قبل قبول العرض المقدم الفائز، دون تحمّل\nأي مسؤولية تجاه العارضين ضمن الحدود ووفق الشروط التالية:\n1. عندما تجد الجهة الشارية ضرورة إحداث تغييرات جوهرية غير متوقعة على\n ملفات التلزيم بعد الاعلان عن الشراء؛\n2. عندما تطرأ تغييرات غير متوقعة على موازنة الجهة الشارية؛\n3. عندما تنتفي الحاجة لموضوع الشراء نتيجة ظروف غير متوقعة وموضوعية،\n وعندها لا يعاد التلزيم خلال الموازنة أو السنة المالية نفسها.\nكما يمكن للجهة الشارية أن تلغي الشراء إذا لم يقدم أي عرض أو اذا قدمت\nعروض غير مقبولة، او في حالة العرض الوحيد المقبول.\nيمكن للجهة الشارية أن تلغي الشراء بعد قبول العرض المقدم الفائز في حال\nتمنّع الملتزم المؤقت عن توقيع العقد، وتقوم بمصادرة ضمان العرض.\nيتم إبلاغ قرار الجهة الشارية الغاء عملية الشراء أو أي من اجراءاته الى كل\nالعارضين المشاركين ضمن مهلة لا تتخطى الخمسة أيام من تاريخ قرار الالغاء،\nإضافة الى ذلك تنشر الجهة الشارية اشعاراً بالغاء عملية الشراء بنفس الطريقة"}, {"o": 13, "l": "المادة 21", "b": "التي نشرت بها المعلومات الأصلية المتعلقة بإجراءات التلزيم وفي المكان\nنفسه، وتعيد العروض التي لم تفتح عند اتخاذ قرار الالغاء الى العارضين\nالذين قدموها كما تعمد إلى تحرير الضمانات المقدمة.\nإرساء العقد\nالمعايير\nمع مراعاة أحكام الفقرة 30 أعلاه، تقوم الجهة الشارية بإرساء التلزيم (أو\nارساء العقد) على العارض المطابق عرضُه للمستندات المطلوبة في ملف التلزيم\nوالذي تمّ اعتباره عارضاً فائزاً وذلك بعد التأكد من أهليته وقدرته على تنفيذ\nالعقد بأفضل صورة ممكنة.\nيجري التلزيم إما على أساس السعر الادنى، أو على أساس العرض الأفضل وفق ما\nهو محدّد في جدول البيانات (القسم الثاني) ويكون العارض مسؤولاً عن تأمين\nالبنود المطلوبة بمواصفاتها وأعدادها المبيّنة في ملف التلزيم وذلك بعد\nتصحيح الأخطاء الحسابية التي تكتشفها اللجنة عند تقييم العرض.\nالتبليغ\nبعد التأكّد من العرض الفائز تبلغ الجهة الشارية الكترونياً وخطياً النتيجة\nللعارض الذي قدّمه من خلال المنصة الالكترونية المركزية لدى هيئة الشراء\nالعام وتنشر على هذه المنصة قرارها بشأن قبول العرض الفائز (التلزيم\nالمؤقت) والذي يدخل حيّز التنفيذ عند إنتهاء فترة التجميد البالغة عشرة أيام\nعمل تبدأ من تاريخ النشر، الذي يجب أن يتضمن على الأقل، المعلومات التالية:\n1. إسم وعنوان العارض الذي قدم العرض الفائز (الملتزم المؤقت)؛\n2. قيمة العرض؛ \n3. مدة فترة التجميد.\nاستلام العارض للتبليغ بإرساء العقد: يقوم العارض بإخطار الجهة الشارية\nكتابياً بتبلّغه بالإرساء، ويضم العارض الى الإقرار تفاصيل الحساب المصرفي\nالذي سيستخدم لغرض تلقّي المدفوعات المستحقة بموجب العقد، وتقدّم هذه\nالتفاصيل في الشكل المطلوب في كتاب القبول.\nيمكن للعارض غير الفائز أو المرفوض عرضه أن يُقدّم إعتراضاً إلى هيئة\nالاعتراضات خطياً خلال فترة التجميد البالغة عشرة أيام عمل والتي تبدأ من"}, {"o": 14, "l": "المادة 21", "b": "تاريخ نشر قرار قبول العرض الفائز. الى حين تشكيل هيئة الاعتراضات الادارية\nيبت النزاعات مجلس شورى الدولة.\nتوقيع العقد\nفور انقضاء فترة التجميد، تقوم الجهة الشارية بإبلاغ الملتزم المؤقت بوجوب\nتوقيع العقد خلال مهلة لا تتعدّى (15) خمسة عشر يوماً.\nيوقِّع المرجع الصالح لدى الجهة الشارية العقد خلال مهلة (15) خمسة عشر يوماً\nمن تاريخ توقيع العقد من قِبَل الملتزم المؤقّت. يمكن أَن تُمدَّد هذه المهلة إلى\nثلاثين يوماً في حالات معيَّنة تحدَّد من قبل المرجع الصالح.\nيبدأ نفاذ العقد عندما يوقِّع الملتزم المؤقّت والمرجع الصالح لدى الجهة\nالشارية عليه.\nالشكاوى\nإجراءات الشكاوى\nيحق لكلّ ذي صفة ومصلحة، بما في ذلك هيئة الشراء العام، الإعتراض على أيّ\nإجراء أو قرار صريح أو ضمني تتّخذه أو تعتمده أو تُطَبِّقه أيّ من الجهات المعنيّة\nبالشراء في المرحلة السابقة لنفاذ العقد، ويكون مخالفاً لأحكام قانون الشراء\nالعام والمبادئ العامة المتعلقة بالشراء العام.\nيقدّم الاعتراض امام هيئة الاعتراضات بحسب الالية المنصوص عنها في الفصل\nالسابع من قانون الشراء العام. والى حين تشكيل هيئة الاعتراضات الادارية\nيبت النزاعات مجلس شورى الدولة.\nالقسم الثاني: جدول البيانات\nData Sheet\nنطاق عملية الشراء\n -----------------------------------------------------------------------\n الجهة الشارية \n ------------------- ---------------------------------------------------\n المشروع \n مصدر التمويل \n عنوان عملية التلزيم \n مرجع التلزيم \n طريقة الشراء \n يمكن الإطلاع \n والحصول على ملف \n التلزيم \n -----------------------------------------------------------------------\n3. العارضون المؤهلون\n ---------------------------------------------------- ------------------\n ] أدخل العدد أو \"لا ينطبق\"] الحد الأقصى لعدد\n الشركاء في تحالف\n الشركات"}, {"o": 15, "l": "المادة 21", "b": "---------------------------------------------------- ------------------\n5. لغة العرض\n+-----------------------------------------------------------------------+\n| لغة العرض هي العربية. |\n| |\n| يمكن ان تكون المراسلات المتبادلة بين العارض والجهة الشارية |\n| ]باللغة.... بالاضافة الى اللغة العربية] / ]باللغة العربية] . |\n| |\n| يمكن تقديم الوثائق المؤيّدة والمستندات التي تشكّل جزءاً من العرض بلغة |\n| أخرى غير العربية على أن تكون مرفقة بتعريب قانوني للمقاطع ذات العلاقة |\n| بالعرض. |\n| |\n| عند التعارض بين النص الأصلي العربي والنص المترجم يؤخذ بالنص باللغة |\n| العربية. |\n+=======================================================================+\n+-----------------------------------------------------------------------+\n7. الإستيضاح، الزيارة الميدانية، اجتماع ما قبل العرض\n7.1 للإستيضاح يمكن التواصل مع الجهة الشارية من خلال:\n -----------------------------------------------------------------------\n السيد (ة) \n ----------------- -----------------------------------------------------\n المسمى الوظيفي \n رقم الطابق – \n الغرفة \n عنوان الشارع \n المدينة / البلدة \n الرمز البريدي \n رقم الهاتف \n الموقع الالكتروني \n البريد الالكتروني \n الموعد الأقصى \n لإستلام طلبات \n إستيضاح العارضين \n هو \n تجيب الجهة \n الشارية على \n الاستيضاحات في \n موعد أقصاه \n -----------------------------------------------------------------------\n7.2 اجتماع الاستيضاح\n -----------------------------------------------------------------------\n التاريخ / الوقت / المكان (في حال الانطباق) أو \"لا ينطبق\"\n -----------------------------------------------------------------------"}, {"o": 16, "l": "المادة 21", "b": "-----------------------------------------------------------------------\n7.3 زيارة الموقع\n -----------------------------------------------------------------------\n التاريخ / الوقت / المكان (في حال الانطباق) أو \"لا ينطبق\"\n -----------------------------------------------------------------------\n -----------------------------------------------------------------------\nالمستندات المكوّنة للعرض \n+-----------------------------------------------------------------------+\n| (في حال طلب أي وثائق اضافية عن تلك المذكورة في الفقرة التاسعة من |\n| القسم الاول (تعليمات العرضين)، تُدرج هذه الوثائق هنا) |\n| |\n| الوثائق الإضافية التي يجب ان يتضمنها العرض الاداري والفني: |\n| |\n| -. ................................................ |\n| |\n| -. ................................................ |\n| |\n| الوثائق الإضافية التي يجب ان يتضمنها العرض المالي: |\n| |\n| -. ................................................ |\n| |\n| -. ................................................ |\n+=======================================================================+\n+-----------------------------------------------------------------------+\nأسعار العرض\n+-----------------------------------------------------------------------+\n| يتم إدخال الأسعار في جدول الأسعار المرفق ربطاً في القسم الخامس |\n| (النماذج). |\n| |\n| يشمل السعر جميع الضرائب والرسوم الواجب تسديدها بسبب العقد. |\n+=======================================================================+\n+-----------------------------------------------------------------------+\nعملة العرض\n -----------------------------------------------------------------------\n ]أدخل العملة]"}, {"o": 17, "l": "المادة 21", "b": "-----------------------------------------------------------------------\n -----------------------------------------------------------------------\n14. الوثائق التي تثبت أهلية العارض\n+-----------------------------------------------------------------------+\n| لاثبات أهليته، على العارض ان يقدّم الوثائق والمستندات التالية: |\n| |\n| 1. كتاب العرض (كتاب التعهّد). |\n| |\n| 2. إذاعة تجارية يُبيَّن فيها صاحب الحق المفوّض بالتوقيع عن العارض ونموذج |\n| توقيعه، أو علم وخبر في حال كان العارض جمعية لا تبغي الربح. |\n| |\n| 3. التفويض القانوني إذا وقّع العرض شخص غير الشخص الذي يملك حق التوقيع |\n| عن العارض، بحسب الإذاعة التجارية أو العلم والخبر في حال كان |\n| العارض جمعية لا تبغي الربح، مصدّق لدى الكاتب العدل. |\n| |\n| 4. سجل عدلي للمفوّض بالتوقيع أو \"من يمثله قانوناً\" لا يتعدى تاريخه |\n| الثلاثة أشهر من تاريخ جلسة فتح العروض. |\n| |\n| 5. عقد الشراكة أو الائتلاف (أو أي عقد آخر يمثل تحالف شركات) مصدق لدى |\n| الكاتب العدل، في حال تقدّم أكثر من عارض بعرض مشترك، سواء كانوا |\n| شركات أو جمعيات لا تبغي الربح أو مزيجاً منهما، على أن يحدّد العقد |\n| رئيس الائتلاف والمسؤولية التضامنية للأعضاء. |\n| |\n| 6. شهادة تسجيل العارض لدى مديرية الضريبة على القيمة المضافة إذا كان |\n| خاضعاً لها، أو شهادة عدم التسجيل إذا لم يكن خاضعاً. |\n| |\n| 7. شهادة تسجيل العارض لدى وزارة المالية – مديرية الواردات. |\n| |\n| 8. براءة ذمة من الصندوق الوطني للضمان الإجتماعي \"شاملة أو صالحة |\n| للإشتراك في الصفقات العمومية\" صالحة بتاريخ جلسة فتح العروض، |\n| تفيد بأن العارض سدّد جميع اشتراكاته. |\n| |\n| 9. إفادة شاملة صادرة عن السجل التجاري تبيّن المؤسسين والأعضاء |\n| والمساهمين أو الشركاء، المفوضين بالتوقيع، المدير، رأس المال، |"}, {"o": 18, "l": "المادة 21", "b": "| نشاط العارض والوقوعات الجارية، أو بيان بالهيئة الإدارية والهيئة |\n| العامة من وزارة الداخلية والبلديات في حال كان العارض جمعية لا |\n| تبغى الربح. |\n| |\n| 10. افادة صادرة عن المرجع المختص تُثبت ان العارض ليس في حالة إفلاس |\n| (غير مطلوب في حال كان العارض جمعية لا تبغى الربح). |\n| |\n| 11. افادة صادرة عن المرجع المختص تُثبت ان العارض ليس في حالة تصفية |\n| قضائية (غير مطلوب في حال كان العارض جمعية لا تبغي الربح). |\n| |\n| 12. ضمان العرض، عند توجّبه، وفقاً لأحكام المادتين 34 و36 من قانون |\n| الشراء العام. |\n| |\n| 13. تصريح من العارض يبيّن فيه صاحب/أصحاب الحق الاقتصادي وفقًا للنموذج |\n| م18 الصادر عن وزارة المالية (كل شخص طبيعي يملك او يسيطر فعلياً |\n| في المحصلة النهائية للنشاط الذي يمارسه العارض، بصورة مباشرة او |\n| غير مباشرة، سواء كان هذا العارض شخص طبيعي او معنوي). |\n| |\n| 14. نسخ عن بطاقات التعريف (هوية / جواز سفر) لصاحب (أصحاب) الحق |\n| الاقتصادي. |\n| |\n| 15. نسخ عن بطاقات التعريف (هوية / جواز سفر) لكل شخص يمثّل العارض (من |\n| ينوب عن العارض في علاقته مع سلطة التعاقد: وكيل قانوني، ممثل |\n| الشخص المعنوي أو المفوّض |\n| بالتوقيع عنه، الخ). |\n| |\n| 16. مستند تصريح النزاهة وفقاً للنموذج المتاح على الموقع الإلكتروني |\n| لهيئة الشراء العام. |\n| |\n| في حال اشتراك عارض أجنبي |\n| |\n| يتوجب على العارض الأجنبي تقديم ما يلي، بالإضافة الى المستندات |\n| الواردة أعلاه: |\n| |\n| 1. شهادة تسجيل الشركة أو المؤسسة لدى المراجع المختصة في بلده على أن |\n| تكون هذه الشهادة مصدقة وفقًا للأصول من المراجع المختصة. |\n| |\n| 2. إفادة من وزارة الاقتصاد والتجارة اللبنانية تُثبت انطباق أحكام |\n| قانون مقاطعة العدو الاسرائيلي على العارض. |\n| |"}, {"o": 19, "l": "المادة 21", "b": "| 3. الإفادات المطلوبة أعلاه بحسب قوانين البلد الذي يوجد فيه العارض، |\n| على أن تكون هذه الإفادات مصدقة وفقًا للأصول من المراجع المختصة. |\n| |\n| كما يتوجب على العارض الأجنبي أن يُراعي أحد الشروط التالية: |\n| |\n| 1. أن يكون من ضمن ائتلاف أو تحالف يضمّ شركة لبنانية على الأقل تتوفر |\n| فيها الشروط المطلوبة بموجب ملف التلزيم. |\n| |\n| 2. أن يعيّن ممثلاً قانونياً مفوّضاً بموجب وكالة قانونية مصدّقة وفقاً |\n| للأصول، يتولّى تمثيله في إجراءات الشراء (وما ينتج عنها من تبعات |\n| قانونية) وتوقيع العقد عنها، مع تحديد عنوان للتبليغ في لبنان. |\n| |\n| ملاحظة: في حالة إجراء التأهيل المسبق لمقدمي العروض المحتملين، يجب |\n| تعديل القائمة أعلاه بشكل مناسب. |\n+=======================================================================+\n+-----------------------------------------------------------------------+\n15. صلاحية العرض\n+-----------------------------------------------------------------------+\n| (أدخل عدد الايام على ألا يقلّ عن ثلاثين يوما) |\n| |\n| (...) يوماً من تاريخ جلسة فتح العروض. |\n+=======================================================================+\n+-----------------------------------------------------------------------+\n16. قيمة وصلاحية ضمان العرض\n+-----------------------------------------------------------------------+\n| ضمان العرض: ]أدخل: \"مطلوب\" أو \"غير مطلوب\"[. |\n| |\n| ]إذا كان ضمان العرض مطلوبا أدخل التالي والا قم بحذفه[. |\n| |\n| قيمة ضمان العرض: ]أدخل القيمة والعملة[. |\n| |\n| صلاحية ضمان العرض : 28 يوماً من تاريخ انتهاء صلاحية العرض المبيّنة في |\n| الفقرة 15 أعلاه. |\n+=======================================================================+"}, {"o": 20, "l": "المادة 21", "b": "+-----------------------------------------------------------------------+\n18. تقديم العروض\n+-----------------------------------------------------------------------+\n| إجراءات التقديم والختم والتأشير هي كما يلي: |\n| |\n| - تُقدّم العروض بحسب نظام الغلافين. |\n| |\n| - يقدّم العرض في الغلاف المختوم الذي توفّره الجهة الشارية لهذا الغرض. |\n| |\n| - عند تقديم العرض، تزوّد الجهة الشارية العارض بإيصال يبيّن فيه رقمٌ |\n| تسلسليٌّ بالإضافة إلى تاريخ تسليم العرض بالساعة واليوم والشهر |\n| والسنة. |\n| |\n| يجب أن يكون الغلافان الداخلي والخارجي على الشكل التالي: |\n| |\n| 1- الغلافان الداخليّان: يجب أن يتضمّن العرض الغلافات التالية: |\n| |\n| 1-1 الغلاف الأول: تذكر عليه عبارة \"غلاف رقم 1 \" المستندات والعرض |\n| الفني\"، وذلك بالإضافة إلى: |\n| |\n| - اسم العارض |\n| |\n| - موضوع العقد |\n| |\n| - تاريخ جلسة فض العروض |\n| |\n| ويتضمن المستندات المطلوبة في الفقرة 9 أعلاه (المستندات المكوّنة للعرض) |\n| باستثناء العرض المالي. |\n| |\n| 1-2 الغلاف الثاني: تذكر عليه عبارة \"غلاف رقم 2 \" العرض المالي\"، وذلك |\n| بالإضافة إلى العبارات المذكورة على الغلاف رقم 1، ويتضمن العرض المالي |\n| بحسب الفقرة 12 من هذا القسم (أسعار العرض). |\n| |\n| يجب تقديم العرض المالي بالعملة المبيّنة في الفقرة 13 (عملة العرض) من |\n| هذا القسم. |\n| |\n| 2- الغلاف الخارجي: يوضع الغلافان (1) و (2) المذكوران أعلاه في غلاف |\n| خارجي موحّد توفّره الجهة الشارية . |\n| |\n| إذا لم تكن الغلافات مختومة ومكتوب عليها على النحو المطلوب، فلن تتحمل |\n| الجهة الشارية أي مسؤولية عن وضع العرض في غير مكانه أو فتحه قبل |\n| الأوان. |\n| |\n| تُقدّم العروض على العنوان التالي: |\n| |\n| ------------------------------------------------------------------ |\n| الجهة الشارية |"}, {"o": 21, "l": "المادة 21", "b": "| ---------------- ------------------------------------------------- |\n| السيد (ة) |\n| |\n| المسمى الوظيفي |\n| |\n| رقم الطابق - |\n| الغرفة |\n| |\n| عنوان الشارع |\n| |\n| المدينة / البلدة |\n| |\n| الرمز البريدي |\n| |\n| رقم الهاتف |\n| ------------------------------------------------------------------ |\n+=======================================================================+\n+-----------------------------------------------------------------------+\n20. الموعد النهائي لتقديم العروض\n+---------------------------------------------------+------------------+\n| [يجب أن يكون التاريخ والوقت هما نفس التاريخ | |\n| والوقت المحددين في الدعوة/ الاعلان. | |\n| | |\n| يجب إعطاء العارضين فترة كافية لإعداد وتقديم | |\n| عروضهم، وان يأخذ تحديد هذه الفترة بعين الاعتبار | |\n| الظروف الخاصة للمشروع وحجم وتعقيد عملية الشراء، | |\n| ووفق المادة الفقرة 3 من"}, {"o": 22, "l": "المادة 20", "b": "المادة 20) من قانون | |\n| الشراء العام يجب أن تُتيح هذه الفترة للعارضين وقتاً | |\n| كافياً لإعداد وتقديم عروضهم]. | |\n+---------------------------------------------------+------------------+\n| ]أدخل التاريخ اليوم والشهر والسنة[ | التاريخ: |\n+---------------------------------------------------+------------------+\n| ]أدخل الوقت[ | الوقت: |\n+---------------------------------------------------+------------------+\n22. فتح العروض\n+------------------------------------------------------+---------------+\n| 22.1 الأشخاص المأذون لهم بحضور جلسة فتح العروض: | |\n| | |\n| 1. ------------------------- | |\n| | |\n| 2. ------------------------- | |\n| | |\n| 3. ------------------------- | |\n| | |\n| 4. ------------------------- الخ. | |\n+------------------------------------------------------+---------------+\n| 22.2 موعد فتح العروض: | |\n+------------------------------------------------------+---------------+\n| ]أدخل التاريخ[ | التاريخ |\n+------------------------------------------------------+---------------+\n| ]أدخل الوقت[ | الوقت |\n+------------------------------------------------------+---------------+\n| 22.3 مكان فتح العروض: | |\n+------------------------------------------------------+---------------+\n| ]أدخل رقم الغرفة والطابق [ | رقم الغرفة/ |\n| | الطابق: |\n+------------------------------------------------------+---------------+\n| ] أدخل إسم المبنى [ | المبنى |\n+------------------------------------------------------+---------------+\n| ]دخل عنوان ورقم الشارع[ | عنوان الشارع: |\n+------------------------------------------------------+---------------+\n| ]أدخل اسم المدينة أو البلدة[ | المدينة: |"}, {"o": 23, "l": "المادة 20", "b": "+------------------------------------------------------+---------------+\n| 22.4 دعوة وسائل الإعلام لحضور جلسة فتح العروض: | |\n| | |\n| ]أدخل: \"سوف\" أو \"لن\"[ تقوم الجهة الشارية بدعوة | |\n| وسائل الاعلام لحضور جلسة فتح العروض | |\n+------------------------------------------------------+---------------+\n31. معايير الإرساء\n -----------------------------------------------------------------------\n يجري التلزيم على أساس ]أدخل: \"السعر الأدنى\" أو \" العرض الافضل \"[\n -----------------------------------------------------------------------\n -----------------------------------------------------------------------\nالقسم الثالث: منهجية التقييم\n+-----------------------------------------------------------------------+\n| Evaluation Methodology |\n| |\n| منهجية تقييم العرض |\n+-----------------------------------------------------------------------+\n الفحص الأولي\n- تدقق لجنة التلزيم العروض الادارية للتحقق من ادراج جميع المستندات\n المطلوبة بموجب ملف التلزيم ضمن العروض الفردية.\n- عند الاقتضاء، يجوز للجهة الشارية أن تطلب من العارض تقديم أي معلومات\n أو وثائق ضرورية ذات صلة وغير متوفّرة، في غضون فترة زمنية معقولة،\n ويعتمد مبدأ المساواة بين جميع العارضين عند تطبيق هذا النص.\n- إن العروض التي لا تستجيب بشكل جوهري لمتطلبات ملف التلزيم لن يتمّ\n النظر فيها وسيتمّ اعتبارها مرفوضة.\nالفحص الدقيق\n- تعتبر الجهة الشارية العرض مستجيباً بشكل جوهري للمتطلبات إذا كان يفي\n بجميع المتطلّبات المبيّنة في ملف التلزيم.\n- يتمّ فحص العروض للتحقق من أنها سليمة، ويجب أن يشمل هذا التحقّق ضمان\n توقيع المستندات بشكل صحيح، وصحة فترة الصلاحية، واستجابة ضمان العرض\n إلى الشروط المطلوبة من حيث الشكل والمضمون والقيمة، واحتواء النماذج"}, {"o": 24, "l": "المادة 20", "b": "على جميع المعلومات المطلوبة.\n- في حال كانت المعلومات أو المستندات المقدّمة في العرض ناقصة أو غير\n مطابقة أو في حال غياب وثيقة معيّنة، يجوز للجهة الشارية الطلب خطياً من\n العارض المعني توضيحات حول عرضه، أو طلب تقديم أو استكمال المعلومات أو\n الوثائق ذات الصلة خلال فترة زمنية محددة، شرط أن تكون كافية.\n- تكون جميع المراسلات خطية احتراماً لمبادىء الشفافية والمساواة في\n المعاملة بين العارضين في طلبات التوضيح أو الاستكمال، وضمن الضوابط\n المحددة في الفقرة 3 من البند الثاني من"}, {"o": 25, "l": "المادة 21", "b": "المادة 21 من قانون الشراء\n العام رقم 244/2021 لجهة عدم امكانية طلب إجراء أو السماح بإجراء أي\n تغيير جوهري في المعلومات المتعلقة بالمؤهلات أو بالعرض المقدّم، بما في\n ذلك التغييرات الرامية الى جعل من ليس مؤهلاً من العارضين مؤهلاً أو جعل\n عرض غير مستوفࣲ للمتطلبات مستوفياً لها.\n- ترفض الجهة الشارية العروض:\n - إذا كان العارض غير مؤهّل بالنظر إلى شروط التأهيل الواردة في القسم\n الرابع (معايير الأهلية والتأهيل)؛\n - إذا كان العرض غير مستجيب جوهرياً للمتطلبات المحددة في القسم\n السادس (المتطلبات)؛ \n - في الحالات الظرفيّة المشار إليها في المادتين 24 أو 25 من قانون\n الشراء العام.\nالتقييم الفني\n- تقيّم لجنة التلزيم المكوّن الفني للعروض فيما يتعلق بمتطلبات القسم\n السادس (المتطلبات).\n- تقوم لجنة التلزيم بفحص النواحي الفنية للعرض المقدّم، للتأكد من أن\n جميع المتطلبات والشروط المحددة في جدول البيانات كما وجميع معايير\n الأهلية والتأهيل المنصوص عليها في القسم الرابع موجودة ومستوفاة دون\n أي تحفظ أو تغيير مادي. إذا رأت اللجنة، بعد فحص الشروط والبنود\n والتقييم الفني، أن العرض لا يستوفي الشروط المطلوبة، يعتبر العرض\n مرفوضاً.\n- يجب على العارض أن يستجيب في عرضه لمدة التنفيذ والتسليم المحددة في\n ملف التلزيم.\n ملاحظة: لن يتمّ تقديم أية مزايا للتسليم المبكر، باستثناء الحالات التي\n يرد النص عليها في شروط العقد العامة والخاصة والتي قد ينظر بها أثناء\n التنفيذ.\n(في حال كان الارساء على العرض الافضل، تستخدم الفقرات التالية،أما في حال\nكان الارساء على السعر الادنى، فتحذف بقية الفقرة 3 ادناه بالاضافة الى\nالفقرة 4)\nيتمّ التقييم الفني وتطبّق الأوزان بحسب الجدول التالي:\nمؤهلات العارض\n -----------------------------------------------------------------------\n القسم الوصف العلامات المتاحة"}, {"o": 26, "l": "المادة 21", "b": "------- --------------------------- -----------------------------------\n -----------------------------------------------------------------------\nالقسم 1: مؤهلات العارض التقنية والفنية\n -------------------------------------------------------------------------\n العلامات الوصف البند\n المتاحة \n -------------- -------------------------------------------------- -------\n -------------------------------------------------------------------------\nالقسم 2: مؤهلات العارض المهنية\n --------------------------------------------------------------------------\n العلامات الوصف البند\n المتاحة \n -------------- --------------------------------------------------- -------\n مجموع التقييم الفني \n --------------------------------------------------------------------------\nان علامة ST=xx هي العلامة الأدنى التي تمكّن العارض من التأهّل فنياً.\nالتقييم المالي\nيتمّ التقييم المالي بحسب المنهجية التالية:\nيعطى العرض المالي الأدنى قيمةً علامة (FM) ثم تحتسب علامات العروض الأخرى\n(SF) بموجب التناسب العكسي كما تنص المعادلة أدناه:\nSF= Financial proposal/FM*100\nتصحيح الأخطاء الحسابية\nتقوم لجنة التلزيم بمراجعة الأخطاء الحسابية فقط للعروض التي اجتازت الفحص\nالدقيق ويتمّ تصحيح الأخطاء على الشكل التالي:\n1. إذا كان هناك من تعارض بين وحدة السعر وبين المجموع الإجمالي للبند،\n الذي ينتج عن ضرب وحدة السعر بالكمية، تُعتمد وحدة السعر ويُصحَّح\n المجموع، إلا إذا رأت اللجنة أن هناك خطأً في مكان الفاصلة (العلامة\n العشرية) لوحدة السعر، يُحتسب عندها المجموع وتُصحّح وحدة السعر؛\n2. إذا كان هناك خطأ في ناتج عمليات جمع المبالغ الإجمالية لكل بند، تُعتمد\n هذه المبالغ الإجمالية ويُصحّح المجموع؛"}, {"o": 27, "l": "المادة 21", "b": "3. إذا كان هناك تعارض بين الأحرف والأرقام في تحديد المبالغ، تُعتمد\n المبالغ المذكورة في الأحرف، إلا إذا كان المبلغ المذكور متعلقاً بخطأ\n حسابي، عندها يصحّح وفقاً للبندين السابقين.\nتقوم لجنة التلزيم بتصحيح قيمة العرض على ضوء تصحيح الأخطاء السابق ذكرها.\nويوافق العارض على أن يعتبر الرقم المصحّح ملزماً له. فإذا رفض العارض قيمة\nعرضه المصحّحة يُرفض عرضه.\nإرساء العقد\n تقوم الجهة الشارية بإرساء العقد على العارض المطابق عرضه للمستندات\n المطلوبة في ملف التلزيم والذي تمّ اعتباره عارضاً فائزاً حيث قدّم ] العرض\n الأدنى سعراً[ أو ]العرض الافضل تقييماً[ وذلك بعد التأكد من أهليته\n وقدراته على تنفيذ العقد بأفضل صورة ممكنة.\n(في حال كان الارساء على العرض الافضل، تستخدم بقية الفقرة 6 ادناه، أما في\nحال كان الارساء على السعر الادنى، فيحذف هذا الجزء من الفقرة)\n تعتمد التعريفات التالية لاحتساب الدرجة النهائية لكل عرض:\n- يُحتسب المجموع الفني ST = الدرجة الفنية للعرض\n- يُحتسب المجموع المالي SF = الدرجة المالية للعرض\n- تُحتسب S = الدرجة النهائية للعرض كالتالي\n S = ST × (number1) % + SF × (number2) %\nيتم ارساء العقد على العرض الذي يحصل على العلامة S الأعلى.\nشروط التأهيل\nالاهلية\nيجب على العارض أن يثبت للجهة الشارية أنه يستوفي معايير الأهلية، بالإضافة\nإلى معايير التأهيل المحددة في القسم الرابع (معايير الأهلية والمؤهلات).\nالوضع المالي\nيجب تقديم المعلومات المالية للفترات الزمنية المذكورة في القسم الرابع\n(معايير الأهلية والتأهيل)، في حال كان ذلك مطلوباً.\nالخبرة\nيجب أن يستوفي العارض الحد الأدنى من معايير الخبرة العامة والإدارية\nوالخاصة للفترة الزمنية المنصوص عليها في القسم الرابع (معايير الأهلية\nوالتأهيل)، في حال كان ذلك مطلوباً.\nعند الإقتضاء، يجوز للجهة الشارية إجراء استفسارات مع عملاء العارض فيما"}, {"o": 28, "l": "المادة 21", "b": "يتعلق بالمشاريع- العقود المرجعية.\nالمعايير البيئية والاجتماعية والصحية والسلامة (ESHS)\nيجب على العارض إيفاء المعايير البيئية والإجتماعية والصحية والسلامة\nالمنصوص عليها في القسم الرابع (معايير الأهلية والتأهيل)، في حال كان ذلك\nمطلوباً.\nمتطلبات محددة فيما يتعلق بتحالف الشركات\n- يجب أن تستوفي جميع الشركات المكوّنة لتحالف الشركات كافة معايير\n التأهيل، ولهذا الغرض يجب إضافة الأرقام ذات الصلة لكل الشركاء للوصول\n إلى القدرة الإجمالية للتحالف؛\n- يجب على كل شريك في تحالف الشركات الإيفاء التام بالمتطلبات المتعلقة\n بسلامة المركز المالي وتاريخ عدم الأداء. يجب على كل شريك في تحالف\n الشركات تلبية حصة- نسبة مئوية معيّنة لمعايير التأهيل، كما هو مذكور في\n القسم الرابع (معايير الأهلية والتأهيل).\nقدرات الموظفين (في حال الانطباق)\n- يجب على العارض توفير موظفين مؤهّلين بشكل مناسب للوظائف المدرجة في\n القسم الرابع، معايير الأهلية والتأهيل.\n- إذا تمّ تحديد شخص ما على أنه غير مؤهّل أو غير مقبول بأي طريقة، فلا\n يرفض العرض، ولكن يتعيّن على العارض استبدال هذا الشخص بشخص آخر يستوفي\n الشروط.\nالقسم الرابع: معايير الأهلية والتأهيل\nEligibility and Qualification Criteria\nمن أجل إثبات الامتثال لمعايير الأهلية المطلوبة في هذا القسم، يجب على\nالعارض تقديم جميع المعلومات المطلوبة وفقاً للنماذج الواردة في القسم\nالخامس (النماذج).\nالزامي\n+----------+-------------------+-----+------+------+-----+---------+\n| المعيار | الجدول رقم 1: | | | | | |\n| | الأهلية | | | | | |\n+==========+===================+=====+======+======+=====+=========+\n| المعيار | المعايير | | | | | الوثائق |\n| الفرعي | | | | | | ا |\n| | | | | | | لمطلوبة |\n+----------+-------------------+-----+------+------+-----+---------+\n| | الشروط | الع | | | | |"}, {"o": 29, "l": "المادة 21", "b": "| | | ارض | | | | |\n+----------+-------------------+-----+------+------+-----+---------+\n| | | ك | م | | | |\n| | | يان | شروع | | | |\n| | | من | مش | | | |\n| |